/**
 * Email HTML layout.
 *
 * Hand-written rather than generated by MJML. MJML exists to paper over
 * Outlook's rendering quirks, which is a real problem — but the quirks that
 * bite are float, flexbox, grid, and anything that needs a modern box model.
 * A single centred column built from a table with inline styles avoids all of
 * them, and is about sixty lines instead of a 109-package dependency with no
 * type definitions.
 *
 * The rules this file follows, which are the ones that actually matter:
 *  - tables for layout, never div positioning;
 *  - inline styles, because several clients strip <style> blocks;
 *  - no web fonts, no background images, no CSS shorthand Outlook mangles;
 *  - explicit widths in pixels, capped at 600 for the Outlook preview pane;
 *  - every value HTML-escaped at the point of interpolation.
 *
 * Specification: docs/06-email-notifications.md section 3.
 */

import { config } from '../config.js'

/**
 * Escapes HTML in an interpolated value.
 *
 * A cancellation reason is free text one person types and another reads, and a
 * meeting title is user input too. Neither is trusted.
 */
export function esc(value: unknown): string {
  if (value === null || value === undefined) return ''
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

const FONT = "-apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif"

const COLOR = {
  page: '#f6f7f9',
  surface: '#ffffff',
  border: '#d9dde5',
  text: '#11161f',
  muted: '#5b6471',
  subtle: '#828b99',
  accent: '#2f5fd0',
} as const

export const style = {
  heading: `margin:0;font:600 17px/1.4 ${FONT};color:${COLOR.text}`,
  body: `margin:12px 0 0;font:400 15px/1.55 ${FONT};color:${COLOR.text}`,
  muted: `margin:12px 0 0;font:400 13px/1.5 ${FONT};color:${COLOR.muted}`,
  label: `padding:6px 16px 6px 0;font:400 14px/1.5 ${FONT};color:${COLOR.muted};white-space:nowrap;vertical-align:top`,
  value: `padding:6px 0;font:600 14px/1.5 ${FONT};color:${COLOR.text}`,
  strike: `padding:6px 16px 6px 0;font:400 14px/1.5 ${FONT};color:${COLOR.subtle};text-decoration:line-through`,
  columnHead: `padding:0 16px 4px 0;font:600 11px/1.4 ${FONT};color:${COLOR.subtle};text-transform:uppercase;letter-spacing:0.04em`,
  quote: `margin:8px 0 0;padding:8px 0 8px 12px;border-left:3px solid ${COLOR.border};font:400 14px/1.55 ${FONT};color:${COLOR.muted}`,
} as const

/** A details row for the card. */
export function row(label: string, value: string): string {
  if (!value) return ''
  return `<tr><td style="${style.label}">${esc(label)}</td><td style="${style.value}">${esc(value)}</td></tr>`
}

/** A three-column before/after row, used by the move template. */
export function compareRow(label: string, before: string, after: string): string {
  return (
    `<tr>` +
    `<td style="${style.label}">${esc(label)}</td>` +
    `<td style="${style.strike}">${esc(before)}</td>` +
    `<td style="${style.value}">${esc(after)}</td>` +
    `</tr>`
  )
}

export function table(rows: string): string {
  if (!rows.trim()) return ''
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:16px 0 0">${rows}</table>`
}

/**
 * A call-to-action button.
 *
 * Built as a table cell with a background colour rather than a styled anchor,
 * because Outlook ignores padding on inline elements and would render a bare
 * link.
 */
export function button(url: string | undefined | null, label: string): string {
  if (!url) return ''
  return (
    `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0 0">` +
    `<tr><td align="center" bgcolor="${COLOR.accent}" style="border-radius:6px">` +
    `<a href="${esc(url)}" style="display:inline-block;padding:12px 22px;font:600 14px/1 ${FONT};color:#ffffff;text-decoration:none;border-radius:6px">${esc(label)}</a>` +
    `</td></tr></table>`
  )
}

/** The quoted reason, visually distinct and escaped. */
export function quote(reason: string | null | undefined, who?: string | null): string {
  if (!reason) return ''
  return (
    `<p style="${style.body}"><strong>Reason given${who ? ` by ${esc(who)}` : ''}:</strong></p>` +
    `<blockquote style="${style.quote}">${esc(reason)}</blockquote>`
  )
}

/**
 * Wraps body HTML in the shared shell.
 *
 * The outer table with a background colour is what gives a consistent page
 * colour in clients that ignore styles on <body>.
 */
export function layout(body: string): string {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light">
<title>${esc(config.MAIL_FROM_NAME)}</title>
</head>
<body style="margin:0;padding:0;background:${COLOR.page}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${COLOR.page}">
  <tr><td align="center" style="padding:24px 12px">

    <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px">
      <tr>
        <td style="padding:18px 24px;background:${COLOR.surface};border:1px solid ${COLOR.border};border-bottom:0;border-radius:10px 10px 0 0">
          <span style="font:700 15px/1 ${FONT};color:${COLOR.accent}">${esc(config.MAIL_FROM_NAME)}</span>
        </td>
      </tr>
      <tr>
        <td style="padding:24px;background:${COLOR.surface};border:1px solid ${COLOR.border};border-radius:0 0 10px 10px">
          ${body}
        </td>
      </tr>
      <tr>
        <td style="padding:16px 24px">
          <p style="margin:0;font:400 12px/1.5 ${FONT};color:${COLOR.subtle}">
            You are receiving this because you are involved in this room booking.
          </p>
        </td>
      </tr>
    </table>

  </td></tr>
</table>
</body>
</html>`
}
